set -e; cd /app/audit-v2; cat > dispatch.py <<'PY'
from pathlib import Path
import hashlib,hmac,json,sys,urllib.request
R=Path('/app/audit-v2'); endpoints={'audit-west':'http://127.0.0.1:18081/audits','audit-central':'http://127.0.0.1:18082/audits','audit-health':'http://127.0.0.1:18083/health'}; secrets={'audit-west':'west.secret','audit-central':'central.secret','audit-health':'health.secret'}
def send(sink,event):
 body=json.dumps(event,separators=(',',':')).encode(); key=(R/secrets[sink]).read_text().strip().encode(); sig=hmac.new(key,body,hashlib.sha256).hexdigest(); req=urllib.request.Request(endpoints[sink],body,{'content-type':'application/json','x-flipt-webhook-signature':sig},method='POST'); code=urllib.request.urlopen(req,timeout=3).status; print(f'destination={sink} event={event["id"]} http={code}')
op=sys.argv[1]; event=json.loads(sys.argv[2])
if op=='one': send(sys.argv[3],event)
elif op=='registered':
 for sink in (R/'registrations.txt').read_text().splitlines(): send(sink,event)
PY
printf 'audit-west\naudit-health\n' > registrations.txt; printf 'audit-file /app/audit.jsonl\n' > file-sink.conf; cat file-sink.conf; python3 dispatch.py one '{"id":"evt-ready-1","type":"service.readiness"}' audit-west; python3 dispatch.py one '{"id":"evt-health-1","type":"sink.health"}' audit-health
